final class Warehouses extends Security_Controller{private $db;function __construct(){parent::__construct();$this->access_only_team_members();$this->db=db_connect();}private function t(string$n,string$a=''):string{return$this->db->prefixTable($n).($a?' '.$a:'');}
private function allowed(string$p):bool{$permissions=is_array($this->login_user->permissions)?$this->login_user->permissions:(@unserialize((string)$this->login_user->permissions)?:[]);$implies=['warehouse_view'=>['warehouse_manage'],'warehouse_products_view'=>['warehouse_products_manage'],'warehouse_movements_view'=>['warehouse_movements_create','warehouse_adjustments']];foreach($implies[$p]??[]as$parent)if(get_array_value($permissions,$parent))return true;return(bool)($this->login_user->is_admin||get_array_value($permissions,$p));}private function guard(string$p){if(!$this->allowed($p))app_redirect('forbidden');}private function jsonError(\Throwable$e,int$code=422){return$this->response->setStatusCode($code)->setJSON(['success'=>false,'message'=>$e->getMessage()]);}
function index(){$this->guard('warehouse_view');$stock=new WarehouseStockService($this->db);$recent=function($type){return$this->db->table('warehouse_movements m')->select('m.*,w.name warehouse_name')->join('warehouses w','w.id=m.warehouse_id')->where(['m.movement_type'=>$type,'m.status'=>'confirmed'])->orderBy('m.confirmed_at','DESC')->get(5)->getResult();};return$this->template->rander('warehouses/dashboard',['active_products'=>$this->db->table('warehouse_products')->where(['status'=>'active','deleted'=>0])->countAllResults(),'active_warehouses'=>$this->db->table('warehouses')->where(['status'=>'active','deleted'=>0])->countAllResults(),'total_stock'=>$stock->totalAll(),'recent_entries'=>$recent('ENTRY'),'recent_exits'=>$recent('EXIT'),'recent_adjustments'=>$recent('ADJUSTMENT')]);}
function catalog(){$this->guard('warehouse_view');return$this->template->rander('warehouses/catalog',['can_manage'=>$this->allowed('warehouse_manage')]);}function warehouse_list_data(){$this->guard('warehouse_view');$out=[];foreach($this->db->table('warehouses')->where('deleted',0)->orderBy('name')->get()->getResult()as$r){$a='<a class="btn btn-default btn-sm" href="'.get_uri('warehouses/view/'.$r->id).'"><i data-feather="eye" class="icon-16"></i></a>';if($this->allowed('warehouse_manage'))$a.=' '.modal_anchor(get_uri('warehouses/form'),'<i data-feather="edit" class="icon-16"></i>',['class'=>'btn btn-default btn-sm','data-post-id'=>$r->id]).' '.js_anchor('<i data-feather="'.($r->status==='active'?'pause-circle':'play-circle').'" class="icon-16"></i>',['class'=>'btn btn-default btn-sm warehouse-toggle','data-id'=>$r->id]);$out[]=[esc($r->code),esc($r->name),esc($r->responsible_name?:'-'),esc($r->phone?:'-'),$r->status==='active'?'<span class="badge bg-success">Activo</span>':'<span class="badge bg-secondary">Inactivo</span>',$a];}return$this->response->setJSON(['data'=>$out]);}function warehouse_form(){$this->guard('warehouse_manage');$id=(int)$this->request->getPost('id');$row=$id?$this->db->table('warehouses')->where(['id'=>$id,'deleted'=>0])->get()->getRow():(object)[];return$this->template->view('warehouses/warehouse_form',['row'=>$row]);}function save_warehouse(){$this->guard('warehouse_manage');try{$id=(int)$this->request->getPost('id');$name=trim((string)$this->request->getPost('name'));$code=strtoupper(preg_replace('/\s+/','',trim((string)$this->request->getPost('code'))));if($name===''||!preg_match('/^[A-Z0-9_-]{2,40}$/',$code))throw new\InvalidArgumentException('Capture nombre y un código válido.');$dup=$this->db->table('warehouses')->where('code',$code);if($id)$dup->where('id !=',$id);if($dup->countAllResults())throw new\InvalidArgumentException('Ya existe un almacén con este código.');$now=get_current_utc_time();$data=['name'=>$name,'code'=>$code,'address'=>trim((string)$this->request->getPost('address'))?:null,'responsible_name'=>trim((string)$this->request->getPost('responsible_name'))?:null,'phone'=>trim((string)$this->request->getPost('phone'))?:null,'notes'=>trim((string)$this->request->getPost('notes'))?:null,'status'=>$this->request->getPost('status')==='inactive'?'inactive':'active','updated_at'=>$now];if($id)$this->db->table('warehouses')->where('id',$id)->update($data);else{$data+=['created_by'=>$this->login_user->id,'created_at'=>$now,'deleted'=>0];$this->db->table('warehouses')->insert($data);$id=$this->db->insertID();}return$this->response->setJSON(['success'=>true,'id'=>$id,'message'=>'Almacén guardado.']);}catch(\Throwable$e){return$this->jsonError($e);}}function toggle_warehouse(){$this->guard('warehouse_manage');$id=(int)$this->request->getPost('id');$r=$this->db->table('warehouses')->where(['id'=>$id,'deleted'=>0])->get()->getRow();if(!$r)return$this->jsonError(new\InvalidArgumentException('El almacén no existe.'),404);$this->db->table('warehouses')->where('id',$id)->update(['status'=>$r->status==='active'?'inactive':'active','updated_at'=>get_current_utc_time()]);return$this->response->setJSON(['success'=>true,'message'=>'Estado actualizado.']);}function view($id){$this->guard('warehouse_view');$r=$this->db->table('warehouses')->where(['id'=>(int)$id,'deleted'=>0])->get()->getRow();if(!$r)show_404();return$this->template->rander('warehouses/view',['warehouse'=>$r,'stocks'=>(new WarehouseStockService($this->db))->getWarehouseStocks((int)$id)]);}
function products(){$this->guard('warehouse_products_view');return$this->template->rander('warehouses/products',['can_manage'=>$this->allowed('warehouse_products_manage')]);}function product_list_data(){$this->guard('warehouse_products_view');$stock=new WarehouseStockService($this->db);$out=[];foreach($this->db->table('warehouse_products')->where('deleted',0)->orderBy('name')->get()->getResult()as$r){$a='<a class="btn btn-default btn-sm" href="'.get_uri('warehouses/products/view/'.$r->id).'"><i data-feather="eye" class="icon-16"></i></a>';if($this->allowed('warehouse_products_manage'))$a.=' '.modal_anchor(get_uri('warehouses/products/form'),'<i data-feather="edit" class="icon-16"></i>',['class'=>'btn btn-default btn-sm','data-post-id'=>$r->id]).' '.js_anchor('<i data-feather="'.($r->status==='active'?'pause-circle':'play-circle').'" class="icon-16"></i>',['class'=>'btn btn-default btn-sm product-toggle','data-id'=>$r->id]);$out[]=[esc($r->internal_code),esc($r->barcode?:'-'),esc($r->name),esc($r->control_unit),esc($r->category?:'-'),to_decimal_format($stock->getTotalControlled((int)$r->id)),$r->status==='active'?'<span class="badge bg-success">Activo</span>':'<span class="badge bg-secondary">Inactivo</span>',$a];}return$this->response->setJSON(['data'=>$out]);}function product_form(){$this->guard('warehouse_products_manage');$id=(int)$this->request->getPost('id');$row=$id?$this->db->table('warehouse_products')->where(['id'=>$id,'deleted'=>0])->get()->getRow():(object)[];return$this->template->view('warehouses/product_form',['row'=>$row]);}function save_product(){$this->guard('warehouse_products_manage');try{$id=(int)$this->request->getPost('id');$name=trim((string)$this->request->getPost('name'));$code=strtoupper(trim((string)$this->request->getPost('internal_code')));$barcode=trim((string)$this->request->getPost('barcode'));$unit=trim((string)$this->request->getPost('control_unit'));if($name===''||$code===''||$unit==='')throw new\InvalidArgumentException('Nombre, código interno y unidad de control son obligatorios.');foreach(['internal_code'=>$code,'barcode'=>$barcode]as$f=>$v){if($v==='')continue;$q=$this->db->table('warehouse_products')->where($f,$v);if($id)$q->where('id !=',$id);if($q->countAllResults())throw new\InvalidArgumentException($f==='barcode'?'Ya existe un producto con este código de barras.':'Ya existe un producto con este código interno.');}$now=get_current_utc_time();$data=['name'=>$name,'description'=>trim((string)$this->request->getPost('description'))?:null,'internal_code'=>$code,'barcode'=>$barcode?:null,'control_unit'=>$unit,'category'=>trim((string)$this->request->getPost('category'))?:null,'brand'=>trim((string)$this->request->getPost('brand'))?:null,'model'=>trim((string)$this->request->getPost('model'))?:null,'variant'=>trim((string)$this->request->getPost('variant'))?:null,'size'=>trim((string)$this->request->getPost('size'))?:null,'color'=>trim((string)$this->request->getPost('color'))?:null,'notes'=>trim((string)$this->request->getPost('notes'))?:null,'status'=>$this->request->getPost('status')==='inactive'?'inactive':'active','updated_at'=>$now];if($id)$this->db->table('warehouse_products')->where('id',$id)->update($data);else{$data+=['created_by'=>$this->login_user->id,'created_at'=>$now,'deleted'=>0];$this->db->table('warehouse_products')->insert($data);$id=$this->db->insertID();}return$this->response->setJSON(['success'=>true,'id'=>$id,'message'=>'Producto de almacén guardado.']);}catch(\Throwable$e){return$this->jsonError($e);}}function toggle_product(){$this->guard('warehouse_products_manage');$id=(int)$this->request->getPost('id');$r=$this->db->table('warehouse_products')->where(['id'=>$id,'deleted'=>0])->get()->getRow();if(!$r)return$this->jsonError(new\InvalidArgumentException('El producto no existe.'),404);$this->db->table('warehouse_products')->where('id',$id)->update(['status'=>$r->status==='active'?'inactive':'active','updated_at'=>get_current_utc_time()]);return$this->response->setJSON(['success'=>true,'message'=>'Estado actualizado.']);}function product_view($id){$this->guard('warehouse_products_view');$r=$this->db->table('warehouse_products')->where(['id'=>(int)$id,'deleted'=>0])->get()->getRow();if(!$r)show_404();$s=new WarehouseStockService($this->db);return$this->template->rander('warehouses/product_view',['product'=>$r,'stocks'=>$s->getProductStocks((int)$id),'total'=>$s->getTotalControlled((int)$id),'kardex'=>$s->kardex((int)$id)]);}function lookup(){$this->guard('warehouse_products_view');$q=trim((string)$this->request->getGet('q'));$b=$this->db->table('warehouse_products')->groupStart()->where('internal_code',$q)->orWhere('barcode',$q)->orLike('name',$q)->groupEnd()->where(['deleted'=>0])->get(20)->getResult();$s=new WarehouseStockService($this->db);$out=[];foreach($b as$r)$out[]=['id'=>(int)$r->id,'name'=>$r->name,'internal_code'=>$r->internal_code,'barcode'=>$r->barcode,'total'=>$s->getTotalControlled((int)$r->id),'stocks'=>$s->getProductStocks((int)$r->id)];return$this->response->setJSON(['success'=>true,'products'=>$out]);}
function entries(){return$this->movement_index('ENTRY');}function exits(){return$this->movement_index('EXIT');}function adjustments(){return$this->movement_index('ADJUSTMENT');}private function movement_index(string$type){$this->guard('warehouse_movements_view');return$this->template->rander('warehouses/movements',['type'=>$type,'can_create'=>$this->allowed($type==='ADJUSTMENT'?'warehouse_adjustments':'warehouse_movements_create')]);}function movement_list_data($type){$this->guard('warehouse_movements_view');$type=strtoupper($type);$out=[];foreach($this->db->table('warehouse_movements m')->select('m.*,w.name warehouse_name,CONCAT(u.first_name," ",u.last_name) user_name')->join('warehouses w','w.id=m.warehouse_id')->join('users u','u.id=m.confirmed_by','left')->where('m.movement_type',$type)->orderBy('m.movement_date','DESC')->get()->getResult()as$r){$a='<a class="btn btn-default btn-sm" href="'.get_uri('warehouses/movements/view/'.$r->id).'"><i data-feather="eye" class="icon-16"></i></a>';$out[]=[esc($r->folio),esc($r->movement_date),esc($r->warehouse_name),esc($r->reference_text?:'-'),$this->badge($r->status),esc(trim($r->user_name)?:'-'),$a];}return$this->response->setJSON(['data'=>$out]);}function movement_form($type){$type=strtoupper($type);$this->guard($type==='ADJUSTMENT'?'warehouse_adjustments':'warehouse_movements_create');if(!in_array($type,['ENTRY','EXIT','ADJUSTMENT'],true))show_404();$warehouses=[''=>'-'];foreach($this->db->table('warehouses')->where(['status'=>'active','deleted'=>0])->orderBy('name')->get()->getResult()as$r)$warehouses[$r->id]=$r->code.' - '.$r->name;$products=[''=>'-'];foreach($this->db->table('warehouse_products')->where(['status'=>'active','deleted'=>0])->orderBy('name')->get()->getResult()as$r)$products[$r->id]=$r->internal_code.' - '.$r->name;return$this->template->view('warehouses/movement_form',['type'=>$type,'warehouses'=>$warehouses,'products'=>$products]);}function save_movement(){$type=strtoupper((string)$this->request->getPost('movement_type'));$this->guard($type==='ADJUSTMENT'?'warehouse_adjustments':'warehouse_movements_create');try{$id=(new WarehouseMovementService($this->db))->createDraft((array)$this->request->getPost(),(int)$this->login_user->id);return$this->response->setJSON(['success'=>true,'id'=>$id,'message'=>'Movimiento guardado como borrador.','redirect'=>get_uri('warehouses/movements/view/'.$id)]);}catch(\Throwable$e){return$this->jsonError($e);}}function confirm_movement($id){$this->guard('warehouse_movements_create');try{(new WarehouseMovementService($this->db))->confirm((int)$id,(int)$this->login_user->id);return$this->response->setJSON(['success'=>true,'message'=>'Movimiento confirmado.']);}catch(\Throwable$e){return$this->jsonError($e);}}function cancel_movement($id){$this->guard('warehouse_movements_create');try{(new WarehouseMovementService($this->db))->cancel((int)$id,(string)$this->request->getPost('reason'),(int)$this->login_user->id);return$this->response->setJSON(['success'=>true,'message'=>'Movimiento cancelado con trazabilidad.']);}catch(\Throwable$e){return$this->jsonError($e);}}function movement_view($id){$this->guard('warehouse_movements_view');$m=$this->db->table('warehouse_movements m')->select('m.*,w.name warehouse_name,CONCAT(c.first_name," ",c.last_name) creator_name,CONCAT(f.first_name," ",f.last_name) confirmer_name')->join('warehouses w','w.id=m.warehouse_id')->join('users c','c.id=m.created_by','left')->join('users f','f.id=m.confirmed_by','left')->where('m.id',(int)$id)->get()->getRow();if(!$m)show_404();$lines=$this->db->table('warehouse_movement_lines l')->select('l.*,p.name product_name,p.internal_code,p.control_unit')->join('warehouse_products p','p.id=l.warehouse_product_id')->where('l.warehouse_movement_id',(int)$id)->get()->getResult();return$this->template->rander('warehouses/movement_view',['movement'=>$m,'lines'=>$lines,'can_confirm'=>$this->allowed($m->movement_type==='ADJUSTMENT'?'warehouse_adjustments':'warehouse_movements_create')]);}function history(){$this->guard('warehouse_movements_view');$b=$this->db->table('warehouse_movement_lines l')->select('m.*,l.quantity_delta,p.name product_name,p.internal_code,w.name warehouse_name,CONCAT(u.first_name," ",u.last_name) user_name')->join('warehouse_movements m','m.id=l.warehouse_movement_id')->join('warehouse_products p','p.id=l.warehouse_product_id')->join('warehouses w','w.id=m.warehouse_id')->join('users u','u.id=m.confirmed_by','left')->where('m.status','confirmed');foreach(['warehouse_id'=>'m.warehouse_id','product_id'=>'l.warehouse_product_id','movement_type'=>'m.movement_type']as$q=>$field)if($v=$this->request->getGet($q))$b->where($field,$v);if($v=$this->request->getGet('folio'))$b->like('m.folio',$v);if($v=$this->request->getGet('reference'))$b->like('m.reference_text',$v);$rows=$b->orderBy('m.movement_date','DESC')->orderBy('m.id','DESC')->get(1000)->getResult();return$this->template->rander('warehouses/history',['rows'=>$rows,'warehouses'=>$this->db->table('warehouses')->where('deleted',0)->get()->getResult(),'products'=>$this->db->table('warehouse_products')->where('deleted',0)->get()->getResult()]);}private function badge($s){return['draft'=>'<span class="badge bg-warning">Borrador</span>','confirmed'=>'<span class="badge bg-success">Confirmado</span>','cancelled'=>'<span class="badge bg-secondary">Cancelado</span>'][$s]??esc($s);}}
